//! Lyric lines translated on the device (the plan: `docs/design/lyrics-second-line.md`,
//! Translation, layer 3; the engine was chosen by `docs/research/lyrics-translation-test.md`).
//!
//! - [`catalog`]: the models there are, each file pinned by its SHA-256 (generated by
//!   `scripts/translation-models.mjs` from Mozilla's model registry).
//! - [`store`]: the models on this device: downloaded only when asked, resumable, checked,
//!   removable.
//! - [`Translator`]: an engine. [`bergamot::Bergamot`] runs Mozilla's Firefox Translations
//!   models here; engines with the listener's own key (DeepL, Microsoft, Google, a language
//!   model) implement it too.
//! - [`translate_song`]: a song's lines in one go, only those in the song's language, each
//!   different line once, kept in a [`cache::SongCache`].
//! - [`Shared`]: one run for many callers asking for the same thing at once (every lyrics
//!   window asks for the song it shows).
//!
//! Nothing here sends a song, a line or anything about the listener anywhere: the only
//! network use is a model's download, from its publisher, when asked.

use std::collections::HashMap;
use std::sync::{Arc, Condvar, Mutex};

pub mod cache;
pub mod catalog;
pub mod langs;
pub mod lines;
pub mod reliable;
pub mod store;

#[cfg(feature = "bergamot")]
pub mod bergamot;
#[cfg(feature = "keyed")]
pub mod keyed;

/// What can go wrong.
#[derive(Debug, thiserror::Error)]
pub enum Error {
    #[error("the download failed: {0}")]
    Network(String),
    #[error("{name} was {got} bytes, {expected} expected")]
    Size {
        name: String,
        expected: u64,
        got: u64,
    },
    #[error("{name} isn't the file expected (its checksum is {got}, {expected} expected)")]
    Checksum {
        name: String,
        expected: String,
        got: String,
    },
    #[error("stopped")]
    Stopped,
    #[error("there is no translation model called {0}")]
    UnknownModel(String),
    #[error("no model translates {from} into {into}")]
    NoModel { from: String, into: String },
    #[error("the {0} model isn't on this device")]
    NotInstalled(String),
    #[error("The translation came back with {got} lines for {expected}, so it isn't shown.")]
    Lines { expected: usize, got: usize },
    #[error("the translation engine failed: {0}")]
    Engine(String),
    // The engines with the listener's own key: said to the listener as they are.
    #[error("Enter your {engine} key in Settings > Lyrics first.")]
    NoKey { engine: String },
    #[error("{engine} didn't accept your key{hint}. Check it in Settings > Lyrics.")]
    BadKey { engine: String, hint: &'static str },
    #[error("Your {engine} quota is used up. Translations with it stop until it renews.")]
    Quota { engine: String },
    #[error("{engine} is busy or getting too many requests. Try again in a minute.")]
    Busy { engine: String },
    #[error("Couldn't reach {engine}. Check the internet connection.")]
    Unreachable { engine: String },
    #[error("{engine} couldn't translate this: {detail}")]
    Refused { engine: String, detail: String },
    #[error(transparent)]
    Io(#[from] std::io::Error),
}

/// A translation engine.
pub trait Translator: Send + Sync {
    /// Its name, as the lyrics say where a line came from (`Translated("bergamot")`).
    fn engine(&self) -> &str;
    /// What would answer for this pair (its model and version), kept with each translation so
    /// a new model translates again; None when it can't translate `from` into `into`.
    fn version(&self, from: &str, into: &str) -> Option<String>;
    /// Each line translated, in order, one for one.
    fn translate(&self, from: &str, into: &str, lines: &[&str]) -> Result<Vec<String>, Error>;
    /// Whether a line of a song in `from` is worth sending: by default only lines in the song's
    /// own script ([`lines::wanted`]); an engine that reads mixed and romanized lines (a
    /// language model) takes every line with words.
    fn wants(&self, from: &str, line: &str) -> bool {
        lines::wanted(from, line)
    }
}

/// A song's lines (`lines`, as sung, in order) translated from `from` into `into`, or the
/// translation kept from before. Only the lines in the song's own language are translated
/// ([`lines::wanted`]); each different line is translated once and repeats share it; a word the
/// engine got stuck repeating is cut back ([`lines::tidy`]). The result has one entry per line.
pub fn translate_song(
    t: &dyn Translator,
    cache: &cache::SongCache,
    from: &str,
    into: &str,
    lines: &[&str],
) -> Result<cache::Entry, Error> {
    let version = t.version(from, into).ok_or_else(|| Error::NoModel {
        from: from.to_owned(),
        into: into.to_owned(),
    })?;
    if let Some(kept) = cache.get(lines, from, into, t.engine(), &version) {
        return Ok(kept);
    }
    let mut unique: Vec<&str> = Vec::new();
    let mut index: HashMap<&str, usize> = HashMap::new();
    let slots: Vec<Option<usize>> = lines
        .iter()
        .map(|l| {
            let l = l.trim();
            t.wants(from, l).then(|| {
                *index.entry(l).or_insert_with(|| {
                    unique.push(l);
                    unique.len() - 1
                })
            })
        })
        .collect();
    let out = if unique.is_empty() {
        Vec::new()
    } else {
        t.translate(from, into, &unique)?
    };
    if out.len() != unique.len() {
        return Err(Error::Lines {
            expected: unique.len(),
            got: out.len(),
        });
    }
    let out: Vec<String> = unique
        .iter()
        .zip(&out)
        .map(|(src, got)| {
            // A line given back as it was (already in your language) has nothing to show.
            let got = lines::tidy(src, got);
            if lines::same(src, &got) {
                String::new()
            } else {
                got
            }
        })
        .collect();
    let entry = cache::Entry {
        from: from.to_owned(),
        into: into.to_owned(),
        engine: t.engine().to_owned(),
        version,
        at_ms: cache::now_ms(),
        lines: slots
            .iter()
            .map(|s| s.map(|i| out[i].clone()).filter(|t| !t.is_empty()))
            .collect(),
    };
    cache.put(lines, &entry)?;
    Ok(entry)
}

/// One run for everyone asking the same thing at the same time: the first caller runs its
/// closure, the others wait and get a copy of that answer. Once answered, the next ask runs
/// again (a caller that wants it kept keeps it, as [`translate_song`] does).
pub struct Shared<T> {
    running: Mutex<HashMap<String, Arc<Slot<T>>>>,
}

enum State<T> {
    Running,
    Done(T),
    /// The run ended without an answer (it panicked): a waiter runs its own.
    Abandoned,
}

struct Slot<T> {
    state: Mutex<State<T>>,
    changed: Condvar,
}

impl<T> Default for Shared<T> {
    fn default() -> Self {
        Shared {
            running: Mutex::new(HashMap::new()),
        }
    }
}

/// Ends the first caller's run: off the list, and its waiters woken, even when it panicked.
struct Finish<'a, T> {
    shared: &'a Shared<T>,
    key: &'a str,
    slot: Arc<Slot<T>>,
}

impl<T> Drop for Finish<'_, T> {
    fn drop(&mut self) {
        self.shared
            .running
            .lock()
            .unwrap_or_else(|e| e.into_inner())
            .remove(self.key);
        let mut state = self.slot.state.lock().unwrap_or_else(|e| e.into_inner());
        if matches!(*state, State::Running) {
            *state = State::Abandoned;
        }
        self.slot.changed.notify_all();
    }
}

impl<T: Clone> Shared<T> {
    pub fn run(&self, key: &str, f: impl FnOnce() -> T) -> T {
        let (slot, first) = {
            let mut running = self.running.lock().unwrap_or_else(|e| e.into_inner());
            match running.get(key) {
                Some(s) => (s.clone(), false),
                None => {
                    let s = Arc::new(Slot {
                        state: Mutex::new(State::Running),
                        changed: Condvar::new(),
                    });
                    running.insert(key.to_owned(), s.clone());
                    (s, true)
                }
            }
        };
        if first {
            let finish = Finish {
                shared: self,
                key,
                slot: slot.clone(),
            };
            let answer = f();
            *slot.state.lock().unwrap_or_else(|e| e.into_inner()) = State::Done(answer.clone());
            drop(finish);
            return answer;
        }
        let mut state = slot.state.lock().unwrap_or_else(|e| e.into_inner());
        loop {
            match &*state {
                State::Done(a) => return a.clone(),
                State::Abandoned => {
                    drop(state);
                    return f();
                }
                State::Running => {
                    state = slot.changed.wait(state).unwrap_or_else(|e| e.into_inner());
                }
            }
        }
    }
}
